<?php
require dirname(__DIR__).'/config.php';admin_required();$pdo=db();verify_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'save';
 if($action==='delete'){$s=$pdo->prepare("DELETE FROM products WHERE id=?");$s->execute([(int)$_POST['id']]);flash('Product deleted.');header('Location: products.php');exit;}
 $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$category=(int)($_POST['category_id']??0)?:null;$price=(float)($_POST['price']??0);$old=trim($_POST['old_price']??'');$stock=max(0,(int)($_POST['stock']??0));$unit=trim($_POST['unit']??'1 item');$description=trim($_POST['description']??'');$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;$image=null;
 if($name===''||$price<0)$error='Please enter a product name and valid price.';
 else {if(!empty($_FILES['image']['name'])&&is_uploaded_file($_FILES['image']['tmp_name'])){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['image']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)$error='Image must be JPG, PNG or WEBP.';elseif($_FILES['image']['size']>3*1024*1024)$error='Image must be under 3 MB.';else{$image='uploads/product-'.bin2hex(random_bytes(8)).'.'.$ext;if(!is_dir(dirname(__DIR__).'/uploads'))mkdir(dirname(__DIR__).'/uploads',0755,true);move_uploaded_file($_FILES['image']['tmp_name'],dirname(__DIR__).'/'.$image);}}
 if(!$error){if($id){$sql="UPDATE products SET category_id=?,name=?,description=?,unit=?,price=?,old_price=?,stock=?,featured=?,active=?".($image?',image=?':'')." WHERE id=?";$vals=[$category,$name,$description,$unit,$price,$old===''?null:(float)$old,$stock,$featured,$active];if($image)$vals[]=$image;$vals[]=$id;$s=$pdo->prepare($sql);$s->execute($vals);}else{$s=$pdo->prepare("INSERT INTO products(category_id,name,description,unit,price,old_price,stock,featured,active,image) VALUES(?,?,?,?,?,?,?,?,?,?)");$s->execute([$category,$name,$description,$unit,$price,$old===''?null:(float)$old,$stock,$featured,$active,$image]);}flash('Product saved.');header('Location: products.php');exit;}}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$cats=$pdo->query("SELECT id,name FROM categories ORDER BY name")->fetchAll();$products=$pdo->query("SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC")->fetchAll();$showForm=$edit||isset($_GET['new'])||$error;
