name="category_id"><option value="">Uncategorised</option><?php foreach($cats as $c): ?><option value="<?=(int)$c['id']?>" <?=((int)($v['category_id']??0)===(int)$c['id']?'selected':'')?>><?=e($c['name'])?></option><?php endforeach; ?></select></label><label>Price (৳)<input type="number" min="0" step=".01" name="price" required value="<?=e((string)($v['price']??''))?>"></label><label>Old price (৳)<input type="number" min="0" step=".01" name="old_price" value="<?=e((string)($v['old_price']??''))?>"></label><label>Unit<input name="unit" value="<?=e($v['unit']??'1 item')?>"></label><label>Stock quantity<input type="number" min="0" name="stock" value="<?=e((string)($v['stock']??0))?>"></label><label class="span-2">Description<textarea name="description" rows="3"><?=e($v['description']??'')?></textarea></label><label class="span-2">Product image (JPG, PNG, WEBP; max 3 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="check-label"><input type="checkbox" name="featured" <?=(!empty($v['featured'])?'checked':'')?>> Featured product</label><label class="check-label"><input type="checkbox" name="active" <?=(!isset($v['active'])||$v['active']?'checked':'')?>> Visible on storefront</label></div><div class="form-actions"><button class="btn primary">Save product</button><a class="btn pale" href="products.php">Cancel</a></div></form><?php endif; ?><section class="panel"><div class="panel-head"><h2>Product list</h2><span class="muted"><?=count($products)?> products</span></div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Visibility</th><th>Action</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><div class="product-cell"><?php if($p['image']): ?><img src="../<?=e($p['image'])?>" alt=""><?php else: ?><span class="mini-thumb"><?=e(mb_substr($p['name'],0,1))?></span><?php endif; ?><div><b><?=e($p['name'])?></b><small><?=e($p['unit'])?></small></div></div></td><td><?=e($p['category_name']??'—')?></td><td><?=money((float)$p['price'])?></td><td><?=$p['stock']?></td><td><span class="status <?=($p['active']?'status-delivered':'status-cancelled')?>"><?=($p['active']?'Visible':'Hidden')?></span></td><td><a class="table-action" href="products.php?edit=<?=(int)$p['id']?>">Edit</a><form class="inline-form" method="post" data-confirm="Delete this product?"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="text-danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></section></main></div><script src="../assets/js/admin.js"></script></body></html>